import React from "react";
import { render, fireEvent, screen, within } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./DataTable.stories";
import { range } from "./mockData";
import DataTable, { DataTableColumnDef, DataTableRow } from ".";
import userEvent from "@testing-library/user-event";

// @ts-ignore
const { Basic } = composeStories(stories);
type RowType = {
  id: string;
  count: number;
  city: string;
  opt: string;
  fir: string;
  longDesc?: string;
};
const dataDynamic = (len: number) => {
  return range(len).map((d: number, index: number) => ({
    count: d,
    city: "city",
    opt: "opt",
    fir: "fir",
    id: "id" + index,
  }));
};

const dataStatic = [
  // creation was absent previously
  {
    id: "id0",
    creation: "Thu, 24 Aug 2023 04:34:12 GMT",
    count: 10,
    city: "tls",
    opt: "opt",
    fir: "fir",
    longDesc: "test",
  },
  {
    id: "id1",
    creation: "Thu, 28 Aug 2023 04:34:12 GMT",
    count: 22,
    city: "blr",
    opt: "opt",
    fir: "fir",
    longDesc: "",
  },
  {
    id: "id2",
    creation: "Thu, 22 Aug 2023 04:34:12 GMT",
    count: 30,
    city: "atl",
    opt: "opt",
    fir: "fir",
    longDesc:
      "test lorem ipsum test lorem ipsum test lorem ipsum test lorem ipsum test lorem ipsum test lorem ipsum test lorem ipsum test lorem ipsum test lorem ipsum",
  },
];

const columns: Array<DataTableColumnDef<RowType>> = [
  { header: "City", accessorKey: "city", size: 90 },
  { header: "OPT", accessorKey: "opt", size: 180 },
  { header: "FIR", accessorKey: "fir", size: 60, enableSorting: false },
  { header: "Count", accessorKey: "count", size: 90, align: "right" },
];

//check the content of last cell in the row
function checkCheckBoxStatus(row: any, checked: boolean) {
  const cells = within(row).getAllByRole("cell");
  const checkBox = within(cells[0]).getByRole("checkbox");
  if (checked) expect(checkBox).toBeChecked();
  else expect(checkBox).not.toBeChecked();
}

//check the content of last cell in the row
function checkCellContent(row: any, index: number, expectedData: string) {
  const cells = within(row).getAllByRole("cell");
  expect(cells[index]).toHaveTextContent(expectedData);
}

describe("DataTable component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("displays pagination if data length exceeds default rowsPerPage", () => {
    render(<DataTable columns={columns} data={dataDynamic(15)} />);
    expect(screen.getByLabelText("Pagination")).toBeDefined();
  });

  it("calls onQueryUpdate in controlled mode", () => {
    const onQueryUpdate = jest.fn();
    render(
      <DataTable
        columns={columns}
        data={dataDynamic(10)}
        onQueryUpdate={onQueryUpdate}
        pageCount={10}
        rowCount={100}
        loading={true}
      />
    );
    expect(screen.getByLabelText("Pagination")).toBeDefined();
    fireEvent.click(screen.getByLabelText("Page 2"));
    expect(onQueryUpdate).toHaveBeenCalledTimes(1);
    expect(onQueryUpdate).toHaveBeenCalledWith({
      pageIndex: 1,
      pageSize: 10,
      sortBy: [],
    });
  });

  it("allow to observe sorting state", () => {
    const onStateUpdate = jest.fn();
    render(<DataTable columns={columns} data={dataStatic} onStateUpdate={onStateUpdate} />);

    // change sort
    fireEvent.click(screen.getByText("Count"));
    const rowsAfterDesc = within(
      screen.getAllByRole("rowgroup")[1]
    ).getAllByRole("row");
    checkCellContent(rowsAfterDesc[0], 3, "30");

    expect(onStateUpdate).toHaveBeenCalledTimes(1);
  });

  it("Check virtualization is working", () => {
    const dataSize = 35;
    render(
      <DataTable
        columns={columns}
        data={dataDynamic(dataSize)}
        pageCount={10}
        rowCount={5}
        height={40}
        allowVirtualization
      />
    );
    expect(screen.getAllByRole("row").length < dataSize).toBeTruthy();
  });

  it("Check onRowClick is working", () => {
    const onQueryUpdate = jest.fn();
    const onRowClick = jest.fn();

    render(
      <DataTable
        columns={columns}
        data={dataStatic}
        onQueryUpdate={onQueryUpdate}
        pageCount={10}
        rowCount={100}
        onRowClick={onRowClick}
      />
    );
    fireEvent.click(screen.getByText("blr"));
    expect(onRowClick).toHaveBeenCalledTimes(1);
    expect(onRowClick).toHaveBeenLastCalledWith(dataStatic[1]);

    // subsequent clicks on same row should dispatch the same data
    fireEvent.click(screen.getByText("blr"));
    expect(onRowClick).toHaveBeenCalledTimes(2);
    expect(onRowClick).toHaveBeenLastCalledWith(dataStatic[1]);
  });

  it("Check onRowSelection is working", () => {
    const onQueryUpdate = jest.fn();
    const onRowSelection = jest.fn();

    const { rerender } = render(
      <DataTable
        columns={columns}
        data={dataStatic}
        onQueryUpdate={onQueryUpdate}
        pageCount={10}
        rowCount={100}
        onRowSelection={onRowSelection}
      />
    );
    fireEvent.click(screen.getByText("blr"));
    fireEvent.click(screen.getByText("tls"));
    fireEvent.click(screen.getByText("atl"));
    expect(onRowSelection).toHaveBeenCalledTimes(3);
    expect(onRowSelection).toHaveBeenCalledWith(dataStatic);

    // reset selected rows
    rerender(
      <DataTable
        columns={columns}
        data={dataStatic}
        onQueryUpdate={onQueryUpdate}
        pageCount={10}
        rowCount={100}
        onRowSelection={onRowSelection}
        defaultSelectedRows={{}}
      />
    );
    expect(onRowSelection).toHaveBeenCalledTimes(4);
    expect(onRowSelection).toHaveBeenCalledWith([]);
  });

  it("Check onRowClick doesn't fire when onRowSelection fires", () => {
    const onRowClick = jest.fn();
    const onRowSelection = jest.fn();

    render(
      <DataTable
        columns={columns}
        data={dataStatic}
        pageCount={10}
        rowCount={100}
        onRowSelection={onRowSelection}
        onRowClick={onRowClick}
      />
    );

    fireEvent.click(screen.getAllByRole("checkbox")[0]);
    expect(onRowSelection).toHaveBeenCalledTimes(1);
    expect(onRowClick).toHaveBeenCalledTimes(0);
  });

  it("Allow expanding rows", () => {
    const onChange = jest.fn();
    render(
      <DataTable
        columns={columns}
        data={dataStatic}
        expandable
        expandableOptions={{
          isRowExpandable: (row: DataTableRow<RowType>) => {
            if (!row.original.longDesc) return false;
            return row.original.longDesc.length > 0;
          },
          renderExpanded: (row: DataTableRow<RowType>) => {
            return <p>{row.original.longDesc}</p>;
          },
          onChange,
        }}
      />
    );
    const expandButtons = screen.getAllByRole("button", {
      name: "Toggle Row Expanded",
    });
    expect(expandButtons).toHaveLength(2);
    fireEvent.click(expandButtons[0]);
    expect(screen.getByLabelText("Expanded row 0")).toBeInTheDocument();
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith({ "0": true });
    fireEvent.click(expandButtons[0]);
    expect(screen.queryByLabelText("Expanded row 0")).not.toBeInTheDocument();
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith({});

    // expand all
    const expandAllButton = screen.getByRole("button", {
      name: "Toggle Row Expanded header",
    });
    fireEvent.click(expandAllButton);
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange).toHaveBeenLastCalledWith({
      "0": true,
      "1": true,
      "2": true,
    });
    // collapse all
    fireEvent.click(expandAllButton);
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith({});
  });

  it("Pagination legend is correct #1141", () => {
    render(
      <DataTable
        columns={columns}
        data={dataDynamic(12)}
        defaultRowsPerPage={5}
      />
    );
    expect(screen.getByLabelText("Pagination")).toBeDefined();
    expect(screen.getAllByLabelText(/Page/)).toHaveLength(3);
    const next = screen.getByLabelText(/Next/);

    expect(screen.getByText("1-5 of 12")).toBeInTheDocument();
    fireEvent.click(next);
    expect(screen.getByText("6-10 of 12")).toBeInTheDocument();
    fireEvent.click(next);
    expect(screen.getByText("11-12 of 12")).toBeInTheDocument();
  });

  it("Does not fire onQueryUpdate when it is updated", () => {
    const onQueryUpdate = jest.fn();
    const onQueryUpdate2 = jest.fn();
    const { rerender } = render(
      <DataTable
        columns={columns}
        data={dataDynamic(10)}
        onQueryUpdate={onQueryUpdate}
        pageCount={2}
        rowCount={20}
      />
    );
    rerender(
      <DataTable
        columns={columns}
        data={dataDynamic(10)}
        onQueryUpdate={onQueryUpdate2}
        pageCount={2}
        rowCount={20}
      />
    );
    expect(onQueryUpdate).toHaveBeenCalledTimes(0);
    expect(onQueryUpdate2).toHaveBeenCalledTimes(0);
    expect(screen.getByLabelText("Pagination")).toBeDefined();
    fireEvent.click(screen.getByLabelText("Page 2"));
    expect(onQueryUpdate2).toHaveBeenCalledTimes(1);
    expect(onQueryUpdate2).toHaveBeenCalledWith({
      pageIndex: 1,
      pageSize: 10,
      sortBy: [],
    });
  });

  it("Allow to reset pagination when controlled", () => {
    const onQueryUpdate = jest.fn();
    const onPageChange = jest.fn(
      (evt: any, page: number) => (pageIndex = page)
    );
    let pageIndex = 1;
    const { rerender } = render(
      <DataTable
        columns={columns}
        data={dataDynamic(20)}
        defaultRowsPerPage={5}
        onQueryUpdate={onQueryUpdate}
        paginationProps={{
          page: pageIndex,
          onPageChange,
        }}
      />
    );
    expect(screen.getByLabelText("Pagination")).toBeDefined();
    expect(screen.getAllByLabelText(/Page/)).toHaveLength(4);

    // goto page 2
    const next = screen.getByLabelText(/Next/);
    fireEvent.click(next);
    expect(onPageChange).toHaveBeenCalledTimes(1);
    expect(pageIndex).toEqual(2);
    // rerender with new controlled page index
    rerender(
      <DataTable
        columns={columns}
        data={dataDynamic(20)}
        defaultRowsPerPage={5}
        onQueryUpdate={onQueryUpdate}
        paginationProps={{
          page: pageIndex,
          onPageChange,
        }}
      />
    );
    expect(
      screen.getByLabelText(/Page 2/).getAttribute("aria-current")
    ).toEqual("page");

    // resetting with new smaller dataset
    pageIndex = 1;
    rerender(
      <DataTable
        columns={columns}
        data={dataDynamic(10)}
        defaultRowsPerPage={5}
        onQueryUpdate={onQueryUpdate}
        paginationProps={{
          page: pageIndex,
          onPageChange,
        }}
      />
    );
    expect(onPageChange).toHaveBeenCalledTimes(1);
    expect(
      screen.getByLabelText(/Page 1/).getAttribute("aria-current")
    ).toEqual("page");
  });

  it("works correctly when rows per page is changed", async () => {
    const onStateUpdate = jest.fn();
    render(
      <DataTable
        columns={columns}
        data={dataDynamic(12)}
        defaultRowsPerPage={5}
        paginationProps={{ showRowsPerPage: true }}
        onStateUpdate={onStateUpdate}
      />
    );

    expect(
      screen.getByRole("navigation", { name: /pagination/i })
    ).toBeDefined();
    expect(screen.getByText("1-5 of 12")).toBeInTheDocument();
    expect(screen.getByLabelText(/Page 3/)).toBeDefined();

    // switch to 10 rows per page
    await userEvent.selectOptions(
      screen.getAllByRole("combobox")[0],
      screen.getByRole("option", { name: "10" })
    );
    expect(screen.getByText("1-10 of 12")).toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: /Page 3/ })
    ).not.toBeInTheDocument();
    expect(onStateUpdate).toHaveBeenCalledTimes(1);
    expect(onStateUpdate).toHaveBeenLastCalledWith({
      rowsPerPage: 10,
      columns: expect.anything(),
      sortBy: [],
    });

    // switch to 25 rows per page
    await userEvent.selectOptions(
      screen.getAllByRole("combobox")[0],
      screen.getByRole("option", { name: "25" })
    );
    expect(screen.getByText("1-12 of 12")).toBeInTheDocument();
    expect(onStateUpdate).toHaveBeenCalledTimes(2);
    expect(onStateUpdate).toHaveBeenLastCalledWith({
      rowsPerPage: 25,
      columns: expect.anything(),
      sortBy: [],
    });
  });

  it("should sort the contents of datatable", () => {
    const sortBy = [{ id: "count", desc: true }];
    render(<DataTable columns={columns} data={dataStatic} sortBy={sortBy} />);

    // initially sorted in desc
    const rows = within(screen.getAllByRole("rowgroup")[1]).getAllByRole("row"); //select body
    checkCellContent(rows[0], 3, "30");
    checkCellContent(rows[1], 3, "22");

    // click to sort in asc
    fireEvent.click(screen.getByText("Count"));
    const rowsAfterDesc = within(
      screen.getAllByRole("rowgroup")[1]
    ).getAllByRole("row"); //select body
    checkCellContent(rowsAfterDesc[0], 3, "10");
    checkCellContent(rowsAfterDesc[1], 3, "22");

    // // click to be unsorted or original
    fireEvent.click(screen.getByText("Count"));
    const rowsAfterAsc = within(
      screen.getAllByRole("rowgroup")[1]
    ).getAllByRole("row"); //select body
    checkCellContent(rowsAfterAsc[0], 3, "10");
    checkCellContent(rowsAfterAsc[1], 3, "22");
  });

  it("Conditionnal expanded rows height", () => {
    const onChange = jest.fn();
    render(
      <DataTable
        columns={columns}
        data={dataStatic}
        expandable
        expandableOptions={{
          getRowHeight: (row: DataTableRow<RowType>) => {
            if (!row.original.longDesc) return 40;
            return row.original.longDesc.length > 10 ? 100 : 60;
          },
          isRowExpandable: (row: DataTableRow<RowType>) => {
            if (!row.original.longDesc) return false;
            return row.original.longDesc.length > 0;
          },
          renderExpanded: (row: DataTableRow<RowType>) => {
            return <p>{row.original.longDesc}</p>;
          },
          onChange,
        }}
      />
    );
    const expandButtons = screen.getAllByRole("button", {
      name: "Toggle Row Expanded",
    });
    fireEvent.click(expandButtons[0]);
    fireEvent.click(expandButtons[1]);
    const bodyRowGroup = screen.getAllByRole("rowgroup")[1];
    // expect body rowgroup height to be :
    // 3xrowHeight + 1x(small expanded row) + 1x(big expanded row) + scrollbarsize
    // 3x40 + 60 + 100 + 16 = 296
    expect(bodyRowGroup).toHaveStyle("height: 296px");
  });

  it("should pre select rows when loading", async () => {
    const onRowSelection = jest.fn(); //needed to enable checkbox, based on which test is performed
    render(
      <DataTable
        columns={columns}
        data={dataStatic}
        onRowSelection={onRowSelection}
        defaultSelectedRows={{ "1": true }}
      />
    );

    const rows = within(screen.getAllByRole("rowgroup")[1]).getAllByRole("row"); //select body
    checkCheckBoxStatus(rows[1], true);
    checkCheckBoxStatus(rows[2], false);
  });

  it("should pre select rows with row.id", async () => {
    const onRowSelection = jest.fn();

    render(
      <DataTable
        columns={columns}
        data={dataStatic}
        onRowSelection={onRowSelection}
        defaultSelectedRows={{ id2: true }}
        getRowId={(row) => row.id}
      />
    );

    const rows = within(screen.getAllByRole("rowgroup")[1]).getAllByRole("row"); //select body
    checkCheckBoxStatus(rows[2], true);
    checkCheckBoxStatus(rows[1], false);
    checkCheckBoxStatus(rows[0], false);
  });
});
